// Install-agnostic DRM canary pairs. Each probe targets a fixture memory
// seeded by init/seed-canary-fixtures.sh (run once after workflow import),
// so a fresh install can satisfy every case.
const CASES = [
  { id: 'drm-001', query: 'what model embeds content in the memory system', expected_top_substr: 'nomic-embed-text' },
  { id: 'drm-002', query: 'vector dimensions of the memory embeddings', expected_top_substr: '768' },
  { id: 'drm-003', query: 'memory tier levels hot warm cold', expected_top_substr: 'hot' },
  { id: 'drm-004', query: 'Memgraph bolt protocol port', expected_top_substr: '7687' },
  { id: 'drm-005', query: 'primary Qdrant collection storing memories', expected_top_substr: 'claude_memories' },
  { id: 'drm-006', query: 'nightly consolidation of episodic memories', expected_top_substr: 'consolidation' },
  { id: 'drm-007', query: 'full-text search over session transcripts', expected_top_substr: 'tsvector' },
  { id: 'drm-008', query: 'weekly probe that measures recall accuracy', expected_top_substr: 'canary' },
  { id: 'drm-009', query: 'the service that generates embeddings for memory storage and recall', expected_top_substr: 'ollama' },
  { id: 'drm-010', query: 'table that records canary run results', expected_top_substr: 'memory_health' },
];
const runId = `drm-${new Date().toISOString().slice(0,10)}-${Math.floor(Math.random()*10000)}`;
return CASES.map(c => ({ json: { ...c, canary_run_id: runId } }));

// Score each case. Hit = top result content contains expected substring (case-insensitive).
const caseInputs = $('Load Canary Pairs').all().map(i => i.json);
const recallResults = $input.all().map(i => i.json);
let hits = 0, lure_fa = 0, unrelated_fa = 0, total = caseInputs.length;
const rows = [];
for (let i = 0; i < caseInputs.length; i++) {
  const c = caseInputs[i];
  const r = recallResults[i] || {};
  const memories = (r.memories || r.results || []);
  const top = memories[0] || {};
  const topContent = String(top.payload?.content || top.content || '').toLowerCase();
  const expectedHit = topContent.includes(String(c.expected_top_substr).toLowerCase());
  if (expectedHit) hits++;
  rows.push({
    canary_run_id: c.canary_run_id,
    query: c.query,
    expected_top_id: null,
    actual_top_id: String(top.id || ''),
    lure_returned: false,
    unrelated_returned: false,
    case_count: total,
  });
}
const hit_rate = total > 0 ? hits/total : 0;
const lure_fa_rate = total > 0 ? lure_fa/total : 0;
const unrelated_fa_rate = total > 0 ? unrelated_fa/total : 0;
// Annotate every row with the aggregate rates.
return rows.map(r => ({ json: { ...r, hit_rate, lure_fa_rate, unrelated_fa_rate } }));
